CREATE POLICY "sales_calls_account_access" ON "sales_calls" AS PERMISSIVE FOR ALL TO "authenticated" USING (public.native_booking_account_member("sales_calls"."user_id")) WITH CHECK (public.native_booking_account_member("sales_calls"."user_id"));--> statement-breakpoint
